[E36] [L383] {"symbol":"org.apache.commons.codec.binary.Hex.decodeHex(char[], byte[], int)","href":"org/apache/commons/codec/binary/Hex.html#decodeHex(char[],byte[],int)","name":"decodeHex","kind":"method","signature":"public static int decodeHex(char[] data, byte[] out, int outOffset) throws DecoderException","summary":"Converts an array of characters representing hexadecimal values into an array of bytes of those same values.","details":"The returned array will be half the length of the passed array, as it takes two characters to represent any given byte. An exception is thrown if the passed char array has an odd number of elements.","params":[{"name":"data","type":"char[]","doc":"An array of characters containing hexadecimal digits."},{"name":"out","type":"byte[]","doc":"A byte array to contain the binary data decoded from the supplied char array."},{"name":"outOffset","type":"int","doc":"The position within out to start writing the decoded bytes."}],"returns":{"type":"int","doc":"The number of bytes written to out."},"throws":[{"type":"DecoderException","doc":"Thrown if an odd number of characters or illegal characters are supplied."}]}
